namespace DocSummary.Models;

public class SummarizeRequest
{
    public required string DocumentText { get; set; }
    public int MaxSentences { get; set; } = 3;
}

namespace DocSummary.Models;

public class SummarizeResponse
{
    public required string Summary { get; set; }
    public int OriginalLength { get; set; }
    public int SummaryLength { get; set; }
}

namespace DocSummary.Services;

public interface IDocumentSummaryService
{
    string Summarize(string documentText, int maxSentences);
}

using System.Text.RegularExpressions;

namespace DocSummary.Services;

public partial class ExtractiveSummaryService : IDocumentSummaryService
{
    public string Summarize(string documentText, int maxSentences)
    {
        var sentences = SplitIntoSentences(documentText);
        if (sentences.Length <= maxSentences)
            return string.Join(" ", sentences);

        var scored = sentences
            .Select((s, i) => new { Sentence = s, Score = ScoreSentence(s, i, sentences) })
            .OrderByDescending(x => x.Score)
            .Take(maxSentences)
            .OrderBy(x => Array.IndexOf(sentences, x.Sentence))
            .Select(x => x.Sentence);

        return string.Join(" ", scored);
    }

    private static string[] SplitIntoSentences(string text)
    {
        return SentenceRegex()
            .Split(text.Trim())
            .Where(s => !string.IsNullOrWhiteSpace(s))
            .Select(s => s.Trim())
            .ToArray();
    }

    private static double ScoreSentence(string sentence, int position, string[] allSentences)
    {
        var words = WordRegex().Split(sentence.ToLowerInvariant())
            .Where(w => w.Length > 3)
            .ToArray();

        // Word frequency across the document
        var allWords = allSentences
            .SelectMany(s => WordRegex().Split(s.ToLowerInvariant()))
            .Where(w => w.Length > 3)
            .GroupBy(w => w)
            .ToDictionary(g => g.Key, g => g.Count());

        double frequencyScore = words.Length > 0
            ? words.Sum(w => allWords.GetValueOrDefault(w, 0)) / (double)words.Length
            : 0;

        // Boost early sentences (positional bias)
        double positionScore = 1.0 / (position + 1);

        // Prefer longer sentences (more informative)
        double lengthScore = Math.Min(words.Length / 10.0, 1.0);

        return frequencyScore + positionScore * 2 + lengthScore;
    }

    [GeneratedRegex(@"(?<=[.!?])\s+")]
    private static partial Regex SentenceRegex();

    [GeneratedRegex(@"\W+")]
    private static partial Regex WordRegex();
}

using DocSummary.Models;
using DocSummary.Services;
using Microsoft.AspNetCore.Mvc;

namespace DocSummary.Controllers;

[ApiController]
[Route("api/[controller]")]
public class SummaryController(IDocumentSummaryService summaryService) : ControllerBase
{
    [HttpPost]
    public ActionResult<SummarizeResponse> Summarize([FromBody] SummarizeRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.DocumentText))
            return BadRequest("DocumentText is required.");

        if (request.MaxSentences < 1)
            return BadRequest("MaxSentences must be at least 1.");

        var summary = summaryService.Summarize(request.DocumentText, request.MaxSentences);

        return Ok(new SummarizeResponse
        {
            Summary = summary,
            OriginalLength = request.DocumentText.Length,
            SummaryLength = summary.Length
        });
    }
}

